mapper.update:
UPDATE review
SET visibility_status = 'HIDDEN', updated_at = #{now}
WHERE id = #{reviewId} AND visibility_status = 'PUBLISHED'

mapper.select:
SELECT COUNT(*)
FROM review
WHERE merchant_id = #{merchantId} AND store_id = #{storeId}

SELECT a.id, a.review_id, a.merchant_id, a.status, a.reason, a.created_at, a.decided_at, r.order_id, r.store_id FROM review_appeal a INNER JOIN review r ON r.id = a.review_id
a.status = #{status}
ORDER BY a.created_at DESC, a.id DESC LIMIT #{offset}, #{limit}
